import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { createHash, randomBytes, randomUUID } from "node:crypto";
import fs from "node:fs/promises";
import http from "node:http";
import path from "node:path";
import { pathToFileURL } from "node:url";

const root = path.resolve(process.argv[2] ?? process.cwd());
const output = path.resolve(process.argv[3] ?? path.join(root, ".artifacts/settings-live-policy/final-effect-media/results"));
await fs.mkdir(output, { recursive: true, mode: 0o700 });
const state = await fs.mkdtemp(path.join(output, "isolated-state-"));
const configPath = path.join(state, "openclaw.json");
for (const name of ["OPENCLAW_GATEWAY_TOKEN", "OPENCLAW_GATEWAY_PASSWORD", "OPENCLAW_AGENT_DIR", "OPENCLAW_CONFIG_INCLUDE_PATH", "OPENCLAW_CONFIG_RAW"]) {
  delete process.env[name];
}
Object.assign(process.env, {
  OPENCLAW_HOME: state,
  OPENCLAW_STATE_DIR: state,
  OPENCLAW_CONFIG_PATH: configPath,
  XDG_CONFIG_HOME: path.join(state, "xdg-config"),
  XDG_CACHE_HOME: path.join(state, "xdg-cache"),
  XDG_DATA_HOME: path.join(state, "xdg-data"),
});
const sourceHead = execFileSync("git", ["rev-parse", "HEAD"], { cwd: root, encoding: "utf8" }).trim();
const evidence = {
  schema: "openclaw-final-effect-media-v1",
  observedHead: sourceHead,
  sourceTree: execFileSync("git", ["rev-parse", "HEAD^{tree}"], { cwd: root, encoding: "utf8" }).trim(),
  harnessSha256: createHash("sha256").update(await fs.readFile(new URL(import.meta.url))).digest("hex"),
  outcome: "running",
  boundary: "Production Gateway HTTP router and HTTP authorization; canonical SQLite session, transcript, and managed attachment owners; real loopback request and ServerResponse.",
  policyPublication: "Canonical setRuntimeConfigSnapshot publication and the server's current resolved-auth getter. The separate CLI Gateway live proof covers config.patch and process continuity.",
  instrumentation: "Only fs.promises.open for the exact synthetic attachment path is wrapped: it performs the real open, retains the real FileHandle, optionally waits on an explicit barrier, and records completion of the real close. Authentication, routing, transcript reads, records, response transport, and returned bytes are not mocked.",
  dependencies: "The production webhook handler is configured disabled; unreachable wake/agent dispatcher injections fail if invoked. No model/provider or external network is used.",
  scenarios: [],
  observations: [],
  cleanup: {},
};
const originalOpen = fs.open;
const sensitiveValues = new Set();
const servers = new Set();
const sockets = new Set();
const pendingResponses = new Set();
const fileProbes = [];
let activeProbe;
let hooksCalls = 0;
let hooksHandler;
let attachmentOpenCount = 0;
let closeAgentDatabases;
let drainGlobals;
let clearConfig;
let currentConfig;
let currentAuth;
let publishConfig;

function observe(event, details = {}) {
  const sequence = evidence.observations.length + 1;
  evidence.observations.push({ sequence, event, ...details });
  return sequence;
}
function deferred() {
  return Promise.withResolvers();
}
async function bounded(promise, label, milliseconds = 45_000) {
  let timer;
  try {
    return await Promise.race([promise, new Promise((_, reject) => {
      timer = setTimeout(() => reject(new Error(`${label} did not settle within its proof budget`)), milliseconds);
    })]);
  } finally {
    clearTimeout(timer);
  }
}
function load(relative) {
  return import(pathToFileURL(path.join(root, relative)).href);
}
function publicError(error) {
  let message = String(error?.message ?? error).replaceAll(state, "[isolated-state]");
  for (const secret of sensitiveValues) message = message.replaceAll(secret, "[synthetic-credential]");
  return { name: error?.name ?? "Error", message };
}
function publish(config, auth) {
  currentConfig = config;
  currentAuth = auth;
  publishConfig(config, config);
}
async function startServer(createServer) {
  const server = createServer({
    clients: new Set(),
    controlUiEnabled: false,
    controlUiBasePath: "",
    resolvedAuth: currentAuth,
    getResolvedAuth: () => currentAuth,
    getRuntimeConfig: () => currentConfig,
    handleHooksRequest: hooksHandler,
  });
  server.on("connection", (socket) => {
    sockets.add(socket);
    socket.once("close", () => sockets.delete(socket));
  });
  server.on("request", (_req, res) => {
    const done = new Promise((resolve) => res.once("close", resolve));
    pendingResponses.add(done);
    done.finally(() => pendingResponses.delete(done));
  });
  servers.add(server);
  await new Promise((resolve, reject) => {
    server.once("error", reject);
    server.listen(0, "127.0.0.1", resolve);
  });
  const address = server.address();
  assert(address && typeof address === "object");
  return { server, port: address.port };
}
async function stopServer(server) {
  await bounded(new Promise((resolve, reject) => server.close((error) => error ? reject(error) : resolve())), "HTTP listener cleanup");
  servers.delete(server);
}
function request(port, route, headers) {
  return new Promise((resolve, reject) => {
    const req = http.get({ hostname: "127.0.0.1", port, path: route, headers: { connection: "close", ...headers } }, (res) => {
      const chunks = [];
      res.on("data", (chunk) => chunks.push(chunk));
      res.once("error", reject);
      res.once("end", () => resolve({ status: res.statusCode, headers: res.headers, body: Buffer.concat(chunks) }));
    });
    req.once("error", reject);
  });
}
function probe(hold) {
  const next = { hold, opened: deferred(), resume: deferred(), closed: deferred(), closeCalls: 0, opens: 0, handle: undefined };
  activeProbe = next;
  fileProbes.push(next);
  return next;
}
async function assertDenied(result) {
  assert.equal(result.status, 401);
  assert.equal(JSON.parse(result.body.toString("utf8")).error.type, "unauthorized");
  for (const name of ["content-disposition", "etag", "last-modified", "content-range"]) {
    assert.equal(result.headers[name], undefined, `revoked response disclosed ${name}`);
  }
  assert.equal(result.headers["content-type"], "application/json; charset=utf-8");
}

try {
  const token = randomBytes(32).toString("base64url");
  const replacementToken = randomBytes(32).toString("base64url");
  sensitiveValues.add(token);
  sensitiveValues.add(replacementToken);
  const tokenAuth = { mode: "token", token, allowTailscale: false };
  const baseConfig = {
    agents: { list: [{ id: "main", workspace: path.join(state, "workspace") }] },
    plugins: { enabled: false },
    gateway: { auth: { mode: "token", token, allowTailscale: false }, controlUi: { enabled: false } },
  };
  await fs.writeFile(configPath, JSON.stringify(baseConfig), { mode: 0o600 });
  const config = await load("src/config/runtime-snapshot.ts");
  publishConfig = config.setRuntimeConfigSnapshot;
  clearConfig = config.clearRuntimeConfigSnapshot;
  publish(baseConfig, tokenAuth);
  const { ensureSessionEntrySync, replaceTranscriptEventsSync } = await load("src/config/sessions/session-accessor.ts");
  const { insertManagedImageRecord, readManagedImageRecord, MANAGED_OUTGOING_ORIGINALS_SUBDIR } = await load("src/gateway/managed-image-record-store.ts");
  const { readSessionMessagesMatchingIdAsync } = await load("src/gateway/session-transcript-readers.ts");
  const { createGatewayHttpServer } = await load("src/gateway/server-http.ts");
  const { createHooksRequestHandler } = await load("src/gateway/server/hooks-request-handler.ts");
  const { createSubsystemLogger } = await load("src/logging/subsystem.ts");
  const unusedHookDispatch = () => { hooksCalls++; throw new Error("Disabled hook unexpectedly dispatched"); };
  hooksHandler = createHooksRequestHandler({
    getHooksConfig: () => null,
    bindHost: "127.0.0.1",
    port: 0,
    logHooks: createSubsystemLogger("media-proof-hooks"),
    dispatchAgentHook: unusedHookDispatch,
    dispatchWakeHook: unusedHookDispatch,
  });
  ({ closeOpenClawAgentDatabasesAsync: closeAgentDatabases } = await load("src/state/openclaw-agent-db.ts"));
  ({ drainGlobalSingletonLifecycleState: drainGlobals } = await load("src/shared/global-singleton.ts"));

  const sessionId = randomUUID();
  const sessionKey = `agent:main:media-proof-${sessionId}`;
  const messageId = "synthetic-media-proof-message";
  const attachmentId = randomUUID();
  const storePath = path.join(state, "agents", "main", "sessions", "sessions.json");
  const scope = { agentId: "main", sessionId, sessionKey, storePath };
  const route = `/api/chat/media/outgoing/${encodeURIComponent(sessionKey)}/${attachmentId}/full`;
  const body = Buffer.from("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAusB9WnXcZ0AAAAASUVORK5CYII=", "base64");
  const mediaRoot = path.join(state, "media");
  const mediaId = `${attachmentId}-synthetic.png`;
  const mediaPath = path.join(mediaRoot, MANAGED_OUTGOING_ORIGINALS_SUBDIR, mediaId);
  await fs.mkdir(path.dirname(mediaPath), { recursive: true });
  await fs.writeFile(mediaPath, body);
  assert.equal(ensureSessionEntrySync(scope, { sessionId, updatedAt: Date.now() }), true);
  assert.equal(replaceTranscriptEventsSync(scope, [
    { type: "session", version: 3, id: sessionId, timestamp: new Date().toISOString(), cwd: state },
    { type: "message", id: messageId, parentId: null, timestamp: new Date().toISOString(), message: { role: "assistant", content: [{ type: "image", url: route, openUrl: route }] } },
  ]), true);
  insertManagedImageRecord({
    attachmentId, sessionKey, agentId: "main", messageId, createdAt: new Date().toISOString(), retentionClass: "history", alt: "Synthetic proof image",
    original: { mediaRoot, mediaId, mediaSubdir: MANAGED_OUTGOING_ORIGINALS_SUBDIR, contentType: "image/png", width: 1, height: 1, sizeBytes: body.length, filename: "synthetic.png" },
  }, state);
  assert.equal((await readManagedImageRecord(attachmentId, state))?.messageId, messageId);
  const messages = await readSessionMessagesMatchingIdAsync(scope, messageId);
  assert(messages.some((message) => message.content?.some((part) => part.url === route)), "canonical transcript reader did not expose the seeded attachment");
  evidence.fixture = { bytes: body.length, sha256: createHash("sha256").update(body).digest("hex"), transcriptReadVerified: true, attachmentRecordReadVerified: true };

  fs.open = async (...args) => {
    const handle = await originalOpen(...args);
    if (String(args[0]) === mediaPath) attachmentOpenCount++;
    if (String(args[0]) === mediaPath && activeProbe) {
      const selected = activeProbe;
      selected.opens++;
      selected.handle = handle;
      selected.openedSequence = observe("real_attachment_file_opened", { held: selected.hold });
      const close = handle.close.bind(handle);
      handle.close = async () => {
        selected.closeCalls++;
        try { return await close(); }
        finally { observe("real_attachment_descriptor_closed", { closed: handle.fd === -1 }); selected.closed.resolve(); }
      };
      selected.opened.resolve();
      if (selected.hold) await selected.resume.promise;
    }
    return handle;
  };

  async function allowed(port, headers, name) {
    const current = probe(false);
    const response = await bounded(request(port, route, headers), name);
    assert.equal(response.status, 200);
    assert.deepEqual(response.body, body);
    assert.equal(response.headers["content-type"], "image/png");
    assert.equal(response.headers["content-length"], String(body.length));
    assert(response.headers["content-disposition"].includes("synthetic.png"));
    await bounded(current.closed.promise, `${name} descriptor cleanup`);
    assert.equal(current.opens, 1);
    assert.equal(current.closeCalls, 1);
    assert.equal(current.handle.fd, -1);
    activeProbe = undefined;
    const acceptedSequence = observe("allowed_literal_bytes_received", { name, status: response.status, bytes: response.body.length });
    evidence.scenarios.push({ name, status: response.status, exactBytes: true, bytes: response.body.length, descriptorClosedOnce: true, acceptedSequence });
  }
  async function revoked(port, headers, change, name) {
    const current = probe(true);
    const responsePromise = request(port, route, headers);
    try {
      await bounded(Promise.race([current.opened.promise, responsePromise.then(() => { throw new Error("Request ended before the filesystem preparation barrier"); })]), `${name} preparation`);
      assert(current.handle.fd >= 0);
      const barrierSequence = observe("prepared_request_barrier_reached", { name, fileDescriptorOpen: true });
      change();
      const revokedSequence = observe("authority_revoked_after_preparation", { name });
      current.resume.resolve();
      const releasedSequence = observe("preparation_released_after_revocation", { name });
      const response = await bounded(responsePromise, name);
      await assertDenied(response);
      const deniedSequence = observe("revoked_response_received", { name, status: response.status });
      assert(barrierSequence < revokedSequence && revokedSequence < releasedSequence && releasedSequence < deniedSequence);
      assert(!response.body.equals(body));
      await bounded(current.closed.promise, `${name} descriptor cleanup`);
      assert.equal(current.opens, 1);
      assert.equal(current.closeCalls, 1);
      assert.equal(current.handle.fd, -1);
      activeProbe = undefined;
      const beforeFreshAdmission = attachmentOpenCount;
      const subsequent = await bounded(request(port, route, headers), `${name} fresh admission`);
      await assertDenied(subsequent);
      assert.equal(attachmentOpenCount, beforeFreshAdmission);
      evidence.scenarios.push({ name, status: response.status, revokedDuringRealOpen: true, privateRepresentationHeaders: false, attachmentBytesDisclosed: false, descriptorClosedOnce: true, subsequentAdmissionStatus: subsequent.status, subsequentFileOpens: 0, barrierSequence, revokedSequence, releasedSequence, deniedSequence });
    } finally {
      current.resume.resolve();
      activeProbe = undefined;
    }
  }

  const tokenServer = await startServer(createGatewayHttpServer);
  await allowed(tokenServer.port, { authorization: `Bearer ${token}` }, "valid bearer admits and serves literal image bytes");
  const beforeBadAdmission = attachmentOpenCount;
  const bad = await bounded(request(tokenServer.port, route, { authorization: "Bearer incorrect-synthetic-token" }), "invalid bearer admission");
  await assertDenied(bad);
  assert.equal(attachmentOpenCount, beforeBadAdmission);
  evidence.scenarios.push({ name: "invalid bearer denied by production admission", status: bad.status });
  await revoked(tokenServer.port, { authorization: `Bearer ${token}` }, () => {
    publish({ ...baseConfig, gateway: { ...baseConfig.gateway, auth: { ...baseConfig.gateway.auth, token: replacementToken } } }, { ...tokenAuth, token: replacementToken });
  }, "credential rotation denies the prepared response and the old bearer");
  await stopServer(tokenServer.server);

  const trustedProxy = { userHeader: "x-forwarded-user", requiredHeaders: ["x-forwarded-proto"], allowUsers: ["media-reader@example.test"], allowLoopback: true };
  const proxyAuth = { mode: "trusted-proxy", trustedProxy, allowTailscale: false };
  const proxyConfig = { ...baseConfig, gateway: { controlUi: { enabled: false }, trustedProxies: ["127.0.0.1"], auth: proxyAuth } };
  publish(proxyConfig, proxyAuth);
  const proxyServer = await startServer(createGatewayHttpServer);
